<?php
declare(strict_types=1);require dirname(__DIR__).'/src/Api.php';require dirname(__DIR__).'/src/Auth.php';require dirname(__DIR__).'/src/Scoring.php';$c=require dirname(__DIR__).'/config/config.php';$origin=$_SERVER['HTTP_ORIGIN']??'';if($origin&&hash_equals($c['allowed_origin'],$origin)){header("Access-Control-Allow-Origin: $origin");header('Vary: Origin');}header('Access-Control-Allow-Headers: Authorization, Content-Type');header('Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS');header("Content-Security-Policy: default-src 'none'; frame-ancestors 'none'");header('X-Content-Type-Options: nosniff');if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(204);exit;}$db=new PDO($c['dsn'],$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$auth=new Auth($db);$user=$auth->user();$path=trim(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),'/');$path=preg_replace('#^api/pegasus/?#','',$path);$method=$_SERVER['REQUEST_METHOD'];
try{
if($method==='GET'&&$path==='categories'){$q=$db->query('SELECT id,slug,name,description,icon,is_linear FROM ctf_categories WHERE is_active=1 ORDER BY id');Api::json($q->fetchAll());}
if($method==='GET'&&$path==='challenges'){$sql="SELECT c.id,c.public_id,c.title,c.slug,c.difficulty,c.scenario AS description,c.learning_objective,c.base_points AS points,k.name category,k.slug category_slug,COALESCE(p.status,'not_started') status,p.attempts,p.hints_used,(c.prerequisite_id IS NOT NULL AND COALESCE(pp.status,'not_started')<>'completed') locked FROM ctf_challenges c JOIN ctf_categories k ON k.id=c.category_id LEFT JOIN ctf_user_progress p ON p.challenge_id=c.id AND p.user_id=? LEFT JOIN ctf_user_progress pp ON pp.challenge_id=c.prerequisite_id AND pp.user_id=? WHERE c.is_active=1";$args=[$user['id'],$user['id']];foreach(['category'=>'k.slug','difficulty'=>'c.difficulty','status'=>'p.status'] as $key=>$col){if(!empty($_GET[$key])){$sql.=" AND $col=?";$args[]=$_GET[$key];}}$sql.=' ORDER BY c.category_id,c.id';$q=$db->prepare($sql);$q->execute($args);Api::json($q->fetchAll());}
if(preg_match('#^challenges/(\d+)$#',$path,$m)&&$method==='GET'){$q=$db->prepare("SELECT c.id,c.public_id,c.title,c.difficulty,c.scenario,c.learning_objective,c.base_points,c.max_attempts,c.time_limit_minutes,c.references_json,k.name category,COALESCE(p.status,'not_started') status,p.attempts,p.hints_used,IF(p.status='completed',c.solution,NULL) solution FROM ctf_challenges c JOIN ctf_categories k ON k.id=c.category_id LEFT JOIN ctf_user_progress p ON p.challenge_id=c.id AND p.user_id=? WHERE c.id=? AND c.is_active=1");$q->execute([$user['id'],$m[1]]);$row=$q->fetch();if(!$row)Api::error('Challenge tidak ditemukan',404);Api::json($row);}
if(preg_match('#^challenges/(\d+)/start$#',$path,$m)&&$method==='POST'){$q=$db->prepare("SELECT c.id FROM ctf_challenges c LEFT JOIN ctf_user_progress prerequisite ON prerequisite.challenge_id=c.prerequisite_id AND prerequisite.user_id=? WHERE c.id=? AND c.is_active=1 AND (c.prerequisite_id IS NULL OR prerequisite.status='completed')");$q->execute([$user['id'],$m[1]]);if(!$q->fetchColumn())Api::error('Challenge tidak ditemukan atau prerequisite belum selesai',409);$q=$db->prepare("INSERT INTO ctf_user_progress(user_id,challenge_id,status,started_at) VALUES(?,?,'in_progress',NOW()) ON DUPLICATE KEY UPDATE status=IF(status='completed',status,'in_progress'),started_at=COALESCE(started_at,NOW())");$q->execute([$user['id'],$m[1]]);Api::json(['status'=>'in_progress'],201);}
if(preg_match('#^challenges/(\d+)/hints/([1-3])$#',$path,$m)&&$method==='POST'){$db->beginTransaction();$q=$db->prepare('SELECT status,hints_used FROM ctf_user_progress WHERE user_id=? AND challenge_id=? FOR UPDATE');$q->execute([$user['id'],$m[1]]);$p=$q->fetch();if(!$p||$p['status']==='completed'||(int)$m[2]>(int)$p['hints_used']+1){$db->rollBack();Api::error('Hint harus dibuka berurutan pada challenge aktif',409);}$q=$db->prepare('SELECT content,penalty_percent FROM ctf_hints WHERE challenge_id=? AND hint_order=?');$q->execute([$m[1],$m[2]]);$h=$q->fetch();if(!$h){$db->rollBack();Api::error('Hint tidak tersedia',404);}$db->prepare('UPDATE ctf_user_progress SET hints_used=GREATEST(hints_used,?) WHERE user_id=? AND challenge_id=?')->execute([$m[2],$user['id'],$m[1]]);$db->commit();Api::json($h);}
if(preg_match('#^challenges/(\d+)/submit$#',$path,$m)&&$method==='POST'){$body=Api::body();$flag=trim((string)($body['flag']??''));if(strlen($flag)>160||!preg_match('/^PEGASUS\{[A-Za-z0-9_:-]{3,140}\}$/',$flag))Api::error('Format flag tidak valid',422);$recent=$db->prepare('SELECT COUNT(*) FROM ctf_submissions WHERE user_id=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 MINUTE)');$recent->execute([$user['id']]);if((int)$recent->fetchColumn()>=10)Api::error('Terlalu banyak percobaan. Tunggu satu menit.',429);$db->beginTransaction();$q=$db->prepare("SELECT c.flag_hash,c.base_points,c.max_attempts,p.status,p.attempts,p.hints_used FROM ctf_challenges c JOIN ctf_user_progress p ON p.challenge_id=c.id AND p.user_id=? WHERE c.id=? FOR UPDATE");$q->execute([$user['id'],$m[1]]);$ch=$q->fetch();if(!$ch){$db->rollBack();Api::error('Mulai challenge terlebih dahulu',409);}if($ch['status']==='completed'||$ch['attempts']>=$ch['max_attempts']){$db->rollBack();Api::error('Submission tidak diizinkan',409);}$correct=password_verify($flag,$ch['flag_hash']);$finger=hash_hmac('sha256',$flag,$c['pepper']);$ip=hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'unknown',$c['pepper']);$ua=hash_hmac('sha256',$_SERVER['HTTP_USER_AGENT']??'unknown',$c['pepper']);$db->prepare('INSERT INTO ctf_submissions(user_id,challenge_id,submitted_hash,is_correct,ip_hash,user_agent_hash) VALUES(?,?,?,?,?,?)')->execute([$user['id'],$m[1],$finger,$correct,$ip,$ua]);$db->prepare('UPDATE ctf_user_progress SET attempts=attempts+1 WHERE user_id=? AND challenge_id=?')->execute([$user['id'],$m[1]]);$points=0;if($correct){$fb=$db->prepare('SELECT COUNT(*) FROM ctf_submissions WHERE challenge_id=? AND is_correct=1');$fb->execute([$m[1]]);$score=Scoring::solve((int)$ch['base_points'],(int)$ch['hints_used'],(int)$fb->fetchColumn()===1);$points=$score['total'];$db->prepare("UPDATE ctf_user_progress SET status='completed',completed_at=NOW(),elapsed_seconds=TIMESTAMPDIFF(SECOND,started_at,NOW()) WHERE user_id=? AND challenge_id=?")->execute([$user['id'],$m[1]]);foreach([['solve',$score['base_after_hints']],['no_hint',$score['no_hint_bonus']],['first_blood',$score['first_blood_bonus']]] as [$type,$value])if($value)$db->prepare('INSERT INTO ctf_scores(user_id,challenge_id,event_type,points,reason) VALUES(?,?,?,?,?)')->execute([$user['id'],$m[1],$type,$value,'Server verified solve']);$done=$db->prepare("SELECT cat.slug,COUNT(*) solved FROM ctf_user_progress p JOIN ctf_challenges x ON x.id=p.challenge_id JOIN ctf_categories cat ON cat.id=x.category_id WHERE p.user_id=? AND p.status='completed' AND x.category_id=(SELECT category_id FROM ctf_challenges WHERE id=?) GROUP BY cat.slug");$done->execute([$user['id'],$m[1]]);$category=$done->fetch();if($category&&(int)$category['solved']===10){$exists=$db->prepare("SELECT COUNT(*) FROM ctf_scores s JOIN ctf_challenges x ON x.id=s.challenge_id JOIN ctf_categories cat ON cat.id=x.category_id WHERE s.user_id=? AND s.event_type='category_bonus' AND cat.slug=?");$exists->execute([$user['id'],$category['slug']]);if(!(int)$exists->fetchColumn()){$db->prepare("INSERT INTO ctf_scores(user_id,challenge_id,event_type,points,reason) VALUES(?,?,'category_bonus',500,'Category completion')")->execute([$user['id'],$m[1]]);$db->prepare("INSERT IGNORE INTO ctf_user_badges(user_id,badge_id) SELECT ?,id FROM ctf_badges WHERE slug=?")->execute([$user['id'],'category-'.$category['slug']]);$points+=500;}}}$db->prepare("INSERT INTO ctf_activity_logs(actor_user_id,target_user_id,action,entity_type,entity_id,metadata_json,ip_hash) VALUES(?,?,'flag_submission','challenge',?,?,?)")->execute([$user['id'],$user['id'],$m[1],json_encode(['correct'=>$correct]),$ip]);$db->commit();Api::json(['correct'=>$correct,'points_awarded'=>$points,'attempt_recorded'=>true]);}
if($method==='GET'&&$path==='leaderboard'){$q=$db->query("SELECT u.id,u.name,COALESCE(SUM(s.points),0) points,COUNT(DISTINCT CASE WHEN s.event_type='solve' THEN s.challenge_id END) completed,COUNT(CASE WHEN s.event_type='first_blood' THEN 1 END) first_bloods FROM users u JOIN ctf_scores s ON s.user_id=u.id GROUP BY u.id,u.name ORDER BY points DESC,completed DESC LIMIT 100");Api::json($q->fetchAll());}
Api::error('Endpoint tidak ditemukan',404);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());Api::error('Terjadi kesalahan server',500);}
